PRAGMA foreign_keys=ON;
PRAGMA user_version=2;
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE families(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE classes(id TEXT PRIMARY KEY,name TEXT NOT NULL,family_id TEXT NOT NULL REFERENCES families(id),base_class_id TEXT REFERENCES classes(id),description TEXT NOT NULL,weapon TEXT NOT NULL);
CREATE TABLE assets(id TEXT PRIMARY KEY,path TEXT NOT NULL,x REAL NOT NULL,y REAL NOT NULL,width REAL NOT NULL CHECK(width>0),height REAL NOT NULL CHECK(height>0),metadata_json TEXT NOT NULL);
CREATE TABLE rarities(id INTEGER PRIMARY KEY CHECK(id BETWEEN 0 AND 4),name TEXT NOT NULL,color TEXT NOT NULL,option_unlock INTEGER NOT NULL);
CREATE TABLE equipment(id TEXT PRIMARY KEY,name TEXT NOT NULL,family_id TEXT NOT NULL REFERENCES families(id),class_id TEXT REFERENCES classes(id),slot TEXT NOT NULL,tier INTEGER NOT NULL CHECK(tier BETWEEN 0 AND 9),rarity INTEGER NOT NULL REFERENCES rarities(id),required_level INTEGER NOT NULL,bonus INTEGER NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),option_summary TEXT NOT NULL);
CREATE UNIQUE INDEX equipment_combination ON equipment(family_id,COALESCE(class_id,''),slot,tier,rarity);
CREATE TABLE monsters(id TEXT PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,health INTEGER NOT NULL,damage INTEGER NOT NULL,speed REAL NOT NULL,attack_range REAL NOT NULL,xp INTEGER NOT NULL,gold INTEGER NOT NULL,ai TEXT NOT NULL,display_height REAL NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),patterns_json TEXT NOT NULL,stagger_json TEXT NOT NULL);
CREATE TABLE floors(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 100),name TEXT NOT NULL,level INTEGER NOT NULL,required_level INTEGER NOT NULL,tier INTEGER NOT NULL,terrain TEXT NOT NULL,guardian_id TEXT NOT NULL REFERENCES monsters(id),is_raid INTEGER NOT NULL,lore TEXT NOT NULL);
CREATE TABLE raids(id TEXT PRIMARY KEY,floor_id INTEGER UNIQUE NOT NULL REFERENCES floors(id),monster_id TEXT NOT NULL REFERENCES monsters(id),name TEXT NOT NULL,health INTEGER NOT NULL,damage INTEGER NOT NULL,xp INTEGER NOT NULL,gold INTEGER NOT NULL,patterns_json TEXT NOT NULL,stagger_json TEXT NOT NULL);
CREATE TABLE appearances(id TEXT PRIMARY KEY,floor_id INTEGER NOT NULL REFERENCES floors(id),monster_id TEXT NOT NULL REFERENCES monsters(id),role TEXT NOT NULL,raid_id TEXT REFERENCES raids(id),level INTEGER NOT NULL,health INTEGER NOT NULL,damage INTEGER NOT NULL,xp INTEGER NOT NULL,gold INTEGER NOT NULL,speed REAL NOT NULL);
CREATE TABLE drops(id TEXT PRIMARY KEY,monster_id TEXT NOT NULL REFERENCES monsters(id),entry_key TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL,slot TEXT,rarity INTEGER NOT NULL REFERENCES rarities(id),chance REAL NOT NULL CHECK(chance BETWEEN 0 AND 1),amount INTEGER NOT NULL CHECK(amount>0),roll_mode TEXT NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),entry_json TEXT NOT NULL,UNIQUE(monster_id,entry_key));
CREATE TABLE raid_drops(id TEXT PRIMARY KEY,raid_id TEXT NOT NULL REFERENCES raids(id),rarity INTEGER NOT NULL REFERENCES rarities(id),chance REAL NOT NULL CHECK(chance BETWEEN 0 AND 1),slot_probability REAL NOT NULL CHECK(slot_probability BETWEEN 0 AND 1),amount INTEGER NOT NULL CHECK(amount=1),tier INTEGER NOT NULL,roll_mode TEXT NOT NULL,UNIQUE(raid_id,rarity));
CREATE TABLE skills(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id),name TEXT NOT NULL,effect TEXT NOT NULL,max_rank INTEGER NOT NULL,required_level INTEGER NOT NULL,parent_mode TEXT NOT NULL,target_id TEXT REFERENCES skills(id),description TEXT NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),node_json TEXT NOT NULL);
CREATE TABLE skill_parents(skill_id TEXT NOT NULL REFERENCES skills(id),parent_id TEXT NOT NULL REFERENCES skills(id),required_rank INTEGER NOT NULL,mode TEXT NOT NULL,PRIMARY KEY(skill_id,parent_id));
CREATE TABLE skill_ranks(skill_id TEXT NOT NULL REFERENCES skills(id),rank INTEGER NOT NULL CHECK(rank>0),metrics_json TEXT NOT NULL,profile_json TEXT NOT NULL,stagger_base REAL NOT NULL CHECK(stagger_base>=0),stagger_value REAL NOT NULL CHECK(stagger_value>=0),stagger_grade TEXT NOT NULL,stagger_multiplier REAL NOT NULL CHECK(stagger_multiplier>=1),PRIMARY KEY(skill_id,rank));
CREATE TABLE exclusive_groups(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id),max_selected INTEGER NOT NULL CHECK(max_selected=1));
CREATE TABLE build_concepts(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id),cluster INTEGER NOT NULL CHECK(cluster BETWEEN 0 AND 4),name TEXT NOT NULL,description TEXT NOT NULL,tradeoff TEXT NOT NULL);
CREATE TABLE build_nodes(id TEXT PRIMARY KEY,class_id TEXT NOT NULL REFERENCES classes(id),type TEXT NOT NULL CHECK(type IN ('original','minor','notable','keystone')),cost INTEGER NOT NULL CHECK(cost>0),max_rank INTEGER NOT NULL CHECK(max_rank>0),required_level INTEGER NOT NULL,exclusive_group TEXT REFERENCES exclusive_groups(id),node_kind TEXT NOT NULL CHECK(node_kind IN ('active','active_module','character_passive','stat_passive')),target_active_id TEXT REFERENCES skills(id),effect_scope TEXT NOT NULL CHECK(effect_scope IN ('self','target_active','character')),concept_id TEXT NOT NULL REFERENCES build_concepts(id),CHECK((node_kind='active_module' AND target_active_id IS NOT NULL AND effect_scope='target_active') OR (node_kind<>'active_module' AND target_active_id IS NULL)));
CREATE TABLE constellations(id TEXT PRIMARY KEY REFERENCES build_nodes(id),name TEXT NOT NULL,cluster INTEGER NOT NULL CHECK(cluster BETWEEN 0 AND 4),cluster_name TEXT NOT NULL,description TEXT NOT NULL,effects_text TEXT NOT NULL,synergy TEXT NOT NULL,tradeoff TEXT NOT NULL,asset_id TEXT NOT NULL REFERENCES assets(id),node_json TEXT NOT NULL);
CREATE TABLE constellation_edges(node_id TEXT NOT NULL REFERENCES constellations(id),parent_id TEXT NOT NULL REFERENCES build_nodes(id),required_rank INTEGER NOT NULL CHECK(required_rank>0),mode TEXT NOT NULL CHECK(mode IN ('any','all')),PRIMARY KEY(node_id,parent_id));
CREATE TABLE effect_definitions(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE constellation_effects(node_id TEXT NOT NULL REFERENCES constellations(id),effect_id TEXT NOT NULL REFERENCES effect_definitions(id),value REAL NOT NULL,PRIMARY KEY(node_id,effect_id));
CREATE TABLE constellation_exclusions(left_id TEXT NOT NULL REFERENCES constellations(id),right_id TEXT NOT NULL REFERENCES constellations(id),PRIMARY KEY(left_id,right_id),CHECK(left_id<right_id));
CREATE VIEW build_edges AS SELECT skill_id node_id,parent_id,required_rank,mode FROM skill_parents UNION ALL SELECT node_id,parent_id,required_rank,mode FROM constellation_edges;
CREATE INDEX appearances_by_monster ON appearances(monster_id,floor_id);
CREATE INDEX drops_by_slot_rarity ON drops(slot,rarity);
CREATE INDEX skills_by_class ON skills(class_id,effect);
CREATE VIEW equipment_dungeon_sources AS
 SELECT DISTINCT e.id equipment_id,d.id drop_id,a.floor_id,d.monster_id,d.chance,'independent_per_entry' probability_kind
 FROM equipment e JOIN drops d ON d.slot=e.slot AND d.rarity=e.rarity
 JOIN appearances a ON a.monster_id=d.monster_id JOIN floors f ON f.id=a.floor_id AND f.tier=e.tier;
CREATE VIEW equipment_raid_sources AS
 SELECT e.id equipment_id,d.id drop_id,r.floor_id,r.monster_id,d.chance grade_chance,d.slot_probability,d.chance*d.slot_probability joint_slot_chance
 FROM equipment e JOIN raid_drops d ON d.rarity=e.rarity AND d.tier=e.tier JOIN raids r ON r.id=d.raid_id;

CREATE TABLE art_sources(id TEXT PRIMARY KEY,path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL CHECK(length(sha256)=64),kind TEXT NOT NULL);
CREATE TABLE art_files(id TEXT PRIMARY KEY,path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL CHECK(length(sha256)=64),bytes INTEGER NOT NULL CHECK(bytes>0),width INTEGER NOT NULL,height INTEGER NOT NULL,representation TEXT NOT NULL CHECK(representation IN ('raster','procedural','rgba_gzip')),source_id TEXT NOT NULL REFERENCES art_sources(id),origin_json TEXT NOT NULL);
CREATE TABLE art_assets(id TEXT PRIMARY KEY,category TEXT NOT NULL,name TEXT NOT NULL,file_id TEXT NOT NULL REFERENCES art_files(id),source_id TEXT NOT NULL REFERENCES art_sources(id),x REAL,y REAL,width REAL,height REAL,frame INTEGER NOT NULL,action TEXT NOT NULL,catalog_path TEXT NOT NULL,metadata_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('applied','available_catalog')),render_cache_file_id TEXT REFERENCES art_files(id));
CREATE TABLE art_uses(id TEXT PRIMARY KEY,art_id TEXT NOT NULL REFERENCES art_assets(id),target_table TEXT NOT NULL,target_id TEXT NOT NULL,consumer TEXT NOT NULL,mapping_json TEXT NOT NULL,usage_kind TEXT NOT NULL CHECK(usage_kind IN ('runtime_mapping','catalog_available')),equipment_id TEXT REFERENCES equipment(id),class_id TEXT REFERENCES classes(id),skill_id TEXT REFERENCES skills(id),constellation_id TEXT REFERENCES constellations(id),monster_id TEXT REFERENCES monsters(id),raid_id TEXT REFERENCES raids(id),appearance_id TEXT REFERENCES appearances(id),floor_id INTEGER REFERENCES floors(id),drop_id TEXT REFERENCES drops(id),facility_id TEXT REFERENCES facilities(id),training_rule_id TEXT REFERENCES training_rules(id),CHECK((target_table IN ('runtime','catalog') AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=0) OR (target_table='equipment' AND equipment_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='classes' AND class_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='skills' AND skill_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='constellations' AND constellation_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='monsters' AND monster_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='raids' AND raid_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='appearances' AND appearance_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='floors' AND floor_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='drops' AND drop_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='facilities' AND facility_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1) OR (target_table='training_rules' AND training_rule_id=target_id AND ((equipment_id IS NOT NULL) + (class_id IS NOT NULL) + (skill_id IS NOT NULL) + (constellation_id IS NOT NULL) + (monster_id IS NOT NULL) + (raid_id IS NOT NULL) + (appearance_id IS NOT NULL) + (floor_id IS NOT NULL) + (drop_id IS NOT NULL) + (facility_id IS NOT NULL) + (training_rule_id IS NOT NULL))=1)),CHECK((target_table='catalog')=(usage_kind='catalog_available')));
CREATE INDEX art_by_category ON art_assets(category,name);
CREATE INDEX art_by_file ON art_assets(file_id);
CREATE INDEX art_uses_by_owner ON art_uses(target_table,target_id);
CREATE INDEX art_uses_by_asset ON art_uses(art_id);
CREATE VIEW art_catalog AS SELECT a.*,f.path runtime_path,f.sha256 runtime_sha256,f.bytes,f.representation,s.path provenance_path,s.sha256 provenance_sha256,f.origin_json,COALESCE(c.path,f.path) render_path,COALESCE(c.sha256,f.sha256) render_sha256,COALESCE(c.representation,f.representation) render_representation FROM art_assets a JOIN art_files f ON f.id=a.file_id JOIN art_sources s ON s.id=a.source_id LEFT JOIN art_files c ON c.id=a.render_cache_file_id;
CREATE VIEW art_usage AS SELECT a.category,a.name,a.id art_id,a.status,u.usage_kind,u.target_table,u.target_id,u.consumer,u.mapping_json,a.runtime_path,a.runtime_sha256,a.x,a.y,a.width,a.height,a.frame,a.action,a.provenance_path,a.render_path,a.render_sha256,a.render_representation FROM art_catalog a JOIN art_uses u ON u.art_id=a.id;

PRAGMA user_version=5;
CREATE TABLE facilities(id TEXT PRIMARY KEY,name TEXT NOT NULL,definition_json TEXT NOT NULL);
CREATE TABLE item_definitions(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE service_operations(id TEXT PRIMARY KEY,facility_id TEXT NOT NULL REFERENCES facilities(id),operation TEXT NOT NULL,definition_json TEXT NOT NULL,UNIQUE(facility_id,operation));
CREATE TABLE service_samples(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES service_operations(id),quantity INTEGER NOT NULL CHECK(quantity>0),gold_cost INTEGER NOT NULL CHECK(gold_cost>=0),gold_reward INTEGER NOT NULL CHECK(gold_reward>=0),definition_json TEXT NOT NULL,CHECK(gold_cost=0 OR gold_reward=0),UNIQUE(id,operation_id));
CREATE TABLE service_inputs(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES service_operations(id),sample_id TEXT NOT NULL,item_id TEXT NOT NULL REFERENCES item_definitions(id),amount INTEGER NOT NULL CHECK(amount>0),FOREIGN KEY(sample_id,operation_id) REFERENCES service_samples(id,operation_id));
CREATE TABLE service_outputs(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES service_operations(id),sample_id TEXT NOT NULL,item_id TEXT NOT NULL REFERENCES item_definitions(id),amount INTEGER NOT NULL CHECK(amount>0),FOREIGN KEY(sample_id,operation_id) REFERENCES service_samples(id,operation_id));
CREATE TABLE service_effects(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES service_operations(id),definition_json TEXT NOT NULL);
CREATE TABLE dungeon_layouts(id TEXT PRIMARY KEY,selection_order INTEGER NOT NULL UNIQUE CHECK(selection_order>=0),definition_json TEXT NOT NULL);
CREATE TABLE training_rules(id TEXT PRIMARY KEY,facility_id TEXT NOT NULL REFERENCES facilities(id),definition_json TEXT NOT NULL);
CREATE TABLE inventory_rules(id TEXT PRIMARY KEY,width INTEGER NOT NULL CHECK(width>0),height INTEGER NOT NULL CHECK(height>0),capacity INTEGER NOT NULL CHECK(capacity=width*height),max_potions INTEGER NOT NULL CHECK(max_potions>0),max_materials INTEGER NOT NULL CHECK(max_materials>0 AND typeof(max_materials)='integer'),definition_json TEXT NOT NULL);

PRAGMA user_version=6;
CREATE TABLE exploration_biomes(id TEXT PRIMARY KEY,name TEXT NOT NULL,tier INTEGER UNIQUE NOT NULL,floor_min INTEGER NOT NULL REFERENCES floors(id),floor_max INTEGER NOT NULL REFERENCES floors(id),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,CHECK(floor_min<=floor_max));
CREATE TABLE exploration_materials(id TEXT PRIMARY KEY REFERENCES item_definitions(id),name TEXT NOT NULL,biome TEXT NOT NULL REFERENCES exploration_biomes(id),tier INTEGER NOT NULL,rarity INTEGER NOT NULL REFERENCES rarities(id),kind TEXT NOT NULL,max_stack INTEGER NOT NULL CHECK(max_stack>0),icon TEXT NOT NULL,binding TEXT NOT NULL,sell_gold INTEGER NOT NULL CHECK(sell_gold>=0),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,UNIQUE(id,biome,tier),UNIQUE(id,tier));
CREATE TABLE exploration_acquisition(id TEXT PRIMARY KEY,material_id TEXT NOT NULL,biome TEXT NOT NULL REFERENCES exploration_biomes(id),tier INTEGER NOT NULL,event TEXT NOT NULL,floor_min INTEGER NOT NULL REFERENCES floors(id),floor_max INTEGER NOT NULL REFERENCES floors(id),chance REAL NOT NULL CHECK(chance BETWEEN 0 AND 1),amount_min INTEGER NOT NULL CHECK(amount_min>0),amount_max INTEGER NOT NULL CHECK(amount_max>=amount_min),recipient TEXT NOT NULL,roll_mode TEXT NOT NULL,risk_bonus INTEGER NOT NULL CHECK(risk_bonus IN (0,1)),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,FOREIGN KEY(material_id,biome,tier) REFERENCES exploration_materials(id,biome,tier),CHECK(floor_min<=floor_max));
CREATE TABLE crafting_recipes(id TEXT PRIMARY KEY,name TEXT NOT NULL,existing_equipment_id TEXT NOT NULL REFERENCES equipment(id),job TEXT NOT NULL REFERENCES classes(id),facility TEXT NOT NULL REFERENCES facilities(id),tier INTEGER NOT NULL,rarity INTEGER NOT NULL REFERENCES rarities(id),level INTEGER NOT NULL CHECK(level>=0),gold INTEGER NOT NULL CHECK(gold>=0),upgrade INTEGER NOT NULL CHECK(upgrade>=0),amount INTEGER NOT NULL CHECK(amount>0),affix TEXT NOT NULL,success_chance REAL NOT NULL CHECK(success_chance BETWEEN 0 AND 1),craft_seconds REAL NOT NULL CHECK(craft_seconds>=0),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL);
CREATE TABLE crafting_ingredients(id TEXT PRIMARY KEY,recipe_id TEXT NOT NULL REFERENCES crafting_recipes(id),material_id TEXT NOT NULL REFERENCES exploration_materials(id),amount INTEGER NOT NULL CHECK(amount>0 AND typeof(amount)='integer'),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,UNIQUE(recipe_id,material_id));
CREATE TABLE alchemy_recipes(id TEXT PRIMARY KEY,name TEXT NOT NULL,facility TEXT NOT NULL REFERENCES facilities(id),biome TEXT NOT NULL REFERENCES exploration_biomes(id),level INTEGER NOT NULL CHECK(level>=0),gold INTEGER NOT NULL CHECK(gold>=0),seconds REAL NOT NULL CHECK(seconds>0),success_chance REAL NOT NULL CHECK(success_chance BETWEEN 0 AND 1),research TEXT NOT NULL,icon TEXT NOT NULL,generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL);
CREATE TABLE alchemy_inputs(id TEXT PRIMARY KEY,recipe_id TEXT NOT NULL REFERENCES alchemy_recipes(id),material_id TEXT NOT NULL REFERENCES exploration_materials(id),amount INTEGER NOT NULL CHECK(amount>0 AND typeof(amount)='integer'),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,UNIQUE(recipe_id,material_id));
CREATE TABLE alchemy_outputs(id TEXT PRIMARY KEY,recipe_id TEXT NOT NULL REFERENCES alchemy_recipes(id),item_id TEXT NOT NULL REFERENCES item_definitions(id),amount INTEGER NOT NULL CHECK(amount>0 AND typeof(amount)='integer'),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,UNIQUE(recipe_id,item_id));
CREATE TABLE enhancement_bands(id TEXT PRIMARY KEY,kind TEXT UNIQUE NOT NULL,target_min INTEGER NOT NULL CHECK(target_min>0),target_max INTEGER NOT NULL CHECK(target_max>=target_min),user_confirmed_success_chance REAL NOT NULL CHECK(user_confirmed_success_chance BETWEEN 0 AND 1),runtime_target_min INTEGER,runtime_target_max INTEGER,runtime_quantity_rule TEXT NOT NULL,runtime_gold_rule TEXT NOT NULL,automatic_activation INTEGER NOT NULL CHECK(automatic_activation IN (0,1)),generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,CHECK((runtime_target_min IS NULL AND runtime_target_max IS NULL) OR (runtime_target_min IS NOT NULL AND runtime_target_max IS NOT NULL AND runtime_target_min>=target_min AND runtime_target_max<=target_max AND runtime_target_min<=runtime_target_max)));
CREATE TABLE enhancement_materials(id TEXT PRIMARY KEY,band_id TEXT NOT NULL REFERENCES enhancement_bands(id),tier INTEGER NOT NULL,material_id TEXT NOT NULL,generation_state TEXT NOT NULL CHECK(generation_state='metadata_projection'),definition_json TEXT NOT NULL,UNIQUE(band_id,tier),FOREIGN KEY(material_id,tier) REFERENCES exploration_materials(id,tier));
CREATE INDEX exploration_drop_search ON exploration_acquisition(material_id,event,floor_min,floor_max);
CREATE INDEX exploration_material_grade ON exploration_materials(rarity,biome,kind);
CREATE INDEX crafting_output_search ON crafting_recipes(existing_equipment_id,rarity);
CREATE INDEX crafting_material_search ON crafting_ingredients(material_id,recipe_id);
CREATE INDEX alchemy_input_search ON alchemy_inputs(material_id,recipe_id);
CREATE INDEX alchemy_output_search ON alchemy_outputs(item_id,recipe_id);
CREATE INDEX enhancement_target_search ON enhancement_bands(target_min,target_max);
CREATE VIEW exploration_material_usage AS
 SELECT material_id,'equipment' usage,recipe_id reference_id,amount FROM crafting_ingredients
 UNION ALL SELECT material_id,'alchemy',recipe_id,amount FROM alchemy_inputs
 UNION ALL SELECT material_id,'enhancement_selection',band_id,NULL FROM enhancement_materials;
